import javax.servlet.http.{HttpServletRequest, HttpServletResponse, HttpSession}
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder
import java.security.SecureRandom
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

object AuthConfig {
  val passwordEncoder = new BCryptPasswordEncoder(12)
  val secureRandom = new SecureRandom()
  val tokenStore = new ConcurrentHashMap[String, String]() // token -> userId

  // Stored bcrypt hashes (pre-computed)
  val userCredentials: Map[String, String] = Map(
    "admin" -> "$2a$12$LJ3m4sMKfJzQKaOGsmKBL.Q7J3H1KdGiR5NE6IpWFCfyJGjT1qxXe",
    "user1" -> "$2a$12$8ZS2Xk9wJmKQp3UVCQxGxOhV7Z5Y6Lm9R4N1T2W3X4Y5Z6A7B8C9D"
  )

  val userRoles: Map[String, String] = Map(
    "admin" -> "ADMIN",
    "user1" -> "USER"
  )
}

object SecurityUtils {
  /**
   * Constant-time comparison to prevent timing attacks.
   * Compares two byte arrays without short-circuiting.
   */
  def constantTimeEquals(a: Array[Byte], b: Array[Byte]): Boolean = {
    if (a == null || b == null) return false
    // Length check - if different lengths, still iterate to avoid timing leak
    val lenDiff = a.length ^ b.length
    var result: Byte = lenDiff.toByte
    val minLen = math.min(a.length, b.length)
    var i = 0
    while (i < minLen) {
      result = (result | (a(i) ^ b(i))).toByte
      i += 1
    }
    result == 0
  }

  def generateToken(): String = {
    val bytes = new Array[Byte](32)
    AuthConfig.secureRandom.nextBytes(bytes)
    Base64.getUrlEncoder.withoutPadding.encodeToString(bytes)
  }

  def escapeHtml(input: String): String = {
    if (input == null) return ""
    input.replace("&", "&amp;").replace("<", "&lt;")
      .replace(">", "&gt;").replace("\"", "&quot;")
      .replace("'", "&#x27;")
  }
}

class AuthenticationController {

  def login(request: HttpServletRequest, response: HttpServletResponse): Unit = {
    val username = request.getParameter("username")
    val password = request.getParameter("password")

    if (username == null || password == null || username.isEmpty || password.isEmpty) {
      response.setStatus(400)
      response.getWriter.write("{\"error\":\"Missing credentials\"}")
      return
    }

    // Verify credentials using BCrypt
    val storedHash = AuthConfig.userCredentials.get(username)
    storedHash match {
      case Some(hash) if AuthConfig.passwordEncoder.matches(password, hash) =>
        // Invalidate old session to prevent fixation
        val oldSession = request.getSession(false)
        if (oldSession != null) {
          oldSession.invalidate()
        }

        // Create new session
        val newSession = request.getSession(true)
        newSession.setAttribute("authenticated", java.lang.Boolean.TRUE)
        newSession.setAttribute("username", username)
        newSession.setMaxInactiveInterval(1800)

        // Generate and store auth token
        val token = SecurityUtils.generateToken()
        newSession.setAttribute("authToken", token)
        AuthConfig.tokenStore.put(token, username)

        response.setStatus(200)
        response.setContentType("application/json")
        response.getWriter.write(
          s"""{"status":"success","token":"${SecurityUtils.escapeHtml(token)}"}"""
        )

      case _ =>
        // Constant-time rejection to prevent user enumeration
        AuthConfig.passwordEncoder.matches(password, AuthConfig.userCredentials.values.head)
        response.setStatus(401)
        response.getWriter.write("{\"error\":\"Invalid credentials\"}")
    }
  }

  def validateApiRequest(request: HttpServletRequest, response: HttpServletResponse): Boolean = {
    val session = request.getSession(false)
    if (session == null) {
      response.setStatus(401)
      response.getWriter.write("{\"error\":\"No session\"}")
      return false
    }

    val authenticated = session.getAttribute("authenticated")
    if (authenticated != java.lang.Boolean.TRUE) {
      response.setStatus(401)
      response.getWriter.write("{\"error\":\"Not authenticated\"}")
      return false
    }

    // Validate bearer token matches session token
    val authHeader = request.getHeader("Authorization")
    if (authHeader == null || !authHeader.startsWith("Bearer ")) {
      response.setStatus(401)
      response.getWriter.write("{\"error\":\"Missing token\"}")
      return false
    }

    val providedToken = authHeader.substring(7)
    val sessionToken = session.getAttribute("authToken").asInstanceOf[String]

    if (sessionToken == null) {
      response.setStatus(401)
      return false
    }

    // Use constant-time comparison to prevent timing attacks
    val tokensMatch = SecurityUtils.constantTimeEquals(
      providedToken.getBytes("UTF-8"),
      sessionToken.getBytes("UTF-8")
    )

    if (!tokensMatch) {
      response.setStatus(403)
      response.getWriter.write("{\"error\":\"Invalid token\"}")
      return false
    }

    true
  }

  def getProfile(request: HttpServletRequest, response: HttpServletResponse): Unit = {
    if (!validateApiRequest(request, response)) return

    val session = request.getSession(false)
    val username = session.getAttribute("username").asInstanceOf[String]
    val role = AuthConfig.userRoles.getOrElse(username, "UNKNOWN")

    response.setStatus(200)
    response.setContentType("application/json")
    response.getWriter.write(
      s"""{"username":"${SecurityUtils.escapeHtml(username)}","role":"${SecurityUtils.escapeHtml(role)}"}"""
    )
  }

  def logout(request: HttpServletRequest, response: HttpServletResponse): Unit = {
    val session = request.getSession(false)
    if (session != null) {
      val token = session.getAttribute("authToken").asInstanceOf[String]
      if (token != null) {
        AuthConfig.tokenStore.remove(token)
      }
      session.invalidate()
    }
    response.setStatus(200)
    response.getWriter.write("{\"status\":\"logged out\"}")
  }
}
